local config = {
  ui_story_32180401_1_1_dialog_content = "Oke, langsung saja ke intinya.",
  ui_story_32180401_1_2_dialog_content = "Pekerjaan ini datang dari saya secara pribadi. Ini juga sedikit tidak konvensional.",
  ui_story_32180401_1_3_dialog_content = "Baik itu tugas dari Cloudrover Guild atau dari Anda, Lady Sheol, saya akan memperlakukannya dengan rasa hormat yang sama.",
  ui_story_32180401_1_4_dialog_content = "Kamu sangat manis, sayang.",
  ui_story_32180401_1_5_dialog_content = "Sebenarnya, saya punya utang macet yang perlu kamu tangani.",
  ui_story_32180401_1_6_dialog_content = "Hutang macet?",
  ui_story_32180401_1_7_dialog_content = "Ya.",
  ui_story_32180401_1_8_dialog_content = "Bukankah Cloudrover memiliki spesialis untuk itu? Isa, misalnya? Meskipun dia tidak lagi bekerja untuk guild tersebut.",
  ui_story_32180401_1_9_dialog_content = "Tapi kamu punya lebih banyak spesialis selain dia, 'kan?",
  ui_story_32180401_1_10_dialog_content = "Benar. Tetapi, seperti yang saya katakan, hutang ini cukup spesial, atau lebih tepatnya, merepotkan.",
  ui_story_32180401_1_11_dialog_content = "Aku takut hanya kamu yang bisa membantu.",
  ui_story_32180401_1_12_dialog_content = "Utang yang bisa mengganggumu sebanyak ini pasti bermasalah...",
  ui_story_32180401_1_13_dialog_content = "(Apakah dia sedang diancam oleh seorang penghindar kewajiban yang sangat licik? Nah, ini seharusnya tidak terjadi, mengingat betapa cerdiknya Lady Sheol...)",
  ui_story_32180401_1_14_dialog_content = "(Tapi, melihat dari ekspresinya, dia tampak sangat terganggu.)",
  ui_story_32180401_1_15_dialog_content = "Saya memiliki saran, Nona Sheol.",
  ui_story_32180401_1_16_dialog_content = "Tolong jelaskan.",
  ui_story_32180401_1_17_dialog_content = "Mari kita kembali dari pensiun Isa!",
  ui_story_32180401_1_18_dialog_content = "Dia adalah kolektor paling profesional yang pernah saya temui! Usaha ini akan berjalan lebih lancar dengan bantuannya!",
  ui_story_32180401_1_19_dialog_content = "Sayangnya, dari apa yang saya tahu tentang dia, dia tidak akan bisa menangani kasus khusus ini.",
  ui_story_32180401_1_20_dialog_content = "Jadi, aku harus pergi sendiri...",
  ui_story_32180401_1_21_dialog_content = "Apakah itu berarti kamu akan menerima pekerjaan itu?",
  ui_story_32180401_1_22_dialog_content = "Saya rasa saya tidak punya pilihan. Saya yakin sejak saat saya masuk ke dalam ruang santai, satu-satunya opsi adalah menerima pekerjaan itu.",
  ui_story_32180401_1_23_dialog_content = "Ah, hanya dalam keadaan seperti itu kamu akan menunjukkan kecerdasan sebenarnya.",
  ui_story_32180401_1_24_dialog_content = "Namun, tentang hutang buruk itu, aku tidak membencinya... Koreksi, aku sangat menyukainya.",
  ui_story_32180401_1_25_dialog_content = "Ibu...!",
  ui_story_32180401_1_26_dialog_content = "<size=45>Ibu?!</size>",
  ui_story_32180401_1_27_dialog_content = "<size=30>Fiuh, inilah yang disebut \"hutang buruk\"...</size>",
  ui_story_32180401_1_28_dialog_content = "Kau kembali, Ibu! Sungguh indah. Aku pikir Ibu meninggalkanku dan tidak akan pernah kembali!",
  ui_story_32180401_1_29_dialog_content = "Hei, siapa ini?",
  ui_story_32180401_1_30_dialog_content = "Oh, aku tahu, ini pasti ayahku! Ayah!",
  ui_story_32180401_1_31_dialog_content = "Ayah?!",
  ui_story_32180401_1_32_dialog_content = "Nona Sheol?!",
  ui_story_32180401_1_33_dialog_content = "Aku tidak tahu kamu punya putri?!",
  ui_story_32180401_1_34_dialog_content = "Jangan panik, sayang. Ini bukan putriku.",
  ui_story_32180401_1_35_dialog_content = "Atau menurutmu aku ini tampak seperti tipe yang bisa mengasuh anak?",
  ui_story_32180401_1_36_dialog_content = "Jadi, siapa anak ini?",
  ui_story_32180401_1_37_dialog_content = "Anak ini adalah \"hutang buruk\" yang saya sebutkan.",
  ui_story_32180401_1_38_dialog_content = "Hah?",
  ui_story_32180401_1_39_dialog_content = "Itu hanya metafora. Tolong angkat dagumu dari lantai.",
  ui_story_32180401_1_40_dialog_content = "Saya memang memiliki hutang yang belum dibayar, tetapi orang yang tidak bertanggung jawab itu kabur dan meninggalkan anak itu sebagai pembayaran.",
  ui_story_32180401_1_41_dialog_content = "Jadi, kenapa hanya aku yang bisa melakukan pekerjaan ini untukmu? Vice akan menjadi pilihan yang lebih baik untuk menjaga anak itu.",
  ui_story_32180401_1_42_dialog_content = "Sebenarnya, aku memintamu untuk mengantarkan anak itu pulang ke rumah.",
  ui_story_32180401_1_43_dialog_content = "Aku...?",
  ui_story_32180401_1_44_dialog_content = "Benar. Mereka menangkap si penghindar hutang. Saat ini dia sedang \"bertobat\" di suatu tempat di bawah pengawasan Cloudrover.",
  ui_story_32180401_1_45_dialog_content = "Saya memerintahkan anak buah saya untuk \"menginterogasi\" dia sedikit, mencoba mencari tahu dari mana dia menculik anak itu, tetapi sia-sia.",
  ui_story_32180401_1_46_dialog_content = "Oleh karena itu, saya membawanya ke banyak tempat dan menunjukkan banyak gambar kepadanya. Tapi dia masih tidak bisa mengingat di mana dia tinggal.",
  ui_story_32180401_1_47_dialog_content = "Akhirnya, dia bahkan menganggapku sebagai ibunya.",
  ui_story_32180401_1_48_dialog_content = "Saya rasa dia mungkin mencari dukungan emosional.",
  ui_story_32180401_1_49_dialog_content = "Apakah kamu akan membawaku ke tempat yang menyenangkan lagi, Bu?",
  ui_story_32180401_1_50_dialog_content = "Wow! Ini hebat! Aku ingin pergi ke sana bersama Ayah dan Ibu!",
  ui_story_32180401_1_51_dialog_content = "Tolong belikan aku es krim yang sangat tinggi lagi, Mama!",
  ui_story_32180401_1_52_dialog_content = "Kamu benar-benar baik pada anak itu, Nona Sheol.",
  ui_story_32180401_1_53_dialog_content = "Sayangnya. Setiap perjalanan untuk mencari kampung halamannya selalu berubah menjadi perjalanan yang menyenangkan baginya.",
  ui_story_32180401_1_54_dialog_content = "Sekarang, Caelestite, kau satu-satunya yang kukenal yang bisa menangani ini.",
  ui_story_32180401_1_55_dialog_content = "Sepertinya aku paham maksudmu.",
  ui_story_32180401_1_56_dialog_content = "Bisakah kamu mengingat bagaimana rasanya ketika kamu bersama orang tua kamu, gadis kecil?",
  ui_story_32180401_1_57_dialog_content = "Kamu tahu Lady Sheol di sini memperlakukanmu seperti keluarga, kan?",
  ui_story_32180401_1_58_dialog_content = "Ehem...",
  ui_story_32180401_1_59_dialog_content = "Jadi, coba ingat jika kamu memiliki perasaan serupa sebelum bertemu dengan Ms. Sheol.",
  ui_story_32180401_1_60_dialog_content = "Oke, saya akan mencobanya!",
  ui_story_32180401_1_61_dialog_content = "Force Boost",
  ui_story_32180401_1_62_dialog_content = "Mau panekuk, Elena?",
  ui_story_32180401_1_63_dialog_content = "Ayo pergi ke taman hari ini, Elena!",
  ui_story_32180401_1_64_dialog_content = "Waktunya bangun, Elena. Matahari sudah terbit sejak beberapa saat lalu.",
  ui_story_32180401_1_65_dialog_content = "Bagaimana?",
  ui_story_32180401_1_66_dialog_content = "Yah, kita tidak benar-benar dalam kegelapan, tapi hanya aku sendirian...",
  ui_story_32180401_1_67_dialog_content = "Tenang saja. Cloudrover akan bekerja sama dengan Anda seratus persen.",
  ui_story_32180401_1_68_dialog_content = "Nona Sheol...",
  ui_story_32180401_1_69_dialog_content = "Ada apa?",
  ui_story_32180401_1_70_dialog_content = "Tidak ada apa-apa. Aku akan bicara denganmu nanti.",
  ui_story_32180401_1_71_dialog_content = "<color=#e8d9bb>Beberapa hari kemudian</color>",
  ui_story_32180401_1_72_dialog_content = "Apakah masalahnya sudah diselesaikan?",
  ui_story_32180401_1_73_dialog_content = "Ya. Ngomong-ngomong, jaringan informasi Cloudrover sangat mengesankan!",
  ui_story_32180401_1_74_dialog_content = "Anak itu enggan, tetapi dia memang kembali ke orang tua kandungnya.",
  ui_story_32180401_1_75_dialog_content = "Bagus.",
  ui_story_32180401_1_76_dialog_content = "Katakan, kenapa kamu tidak ingin ikut, Lady Sheol?",
  ui_story_32180401_1_77_dialog_content = "Apakah itu perlu?",
  ui_story_32180401_1_78_dialog_content = "Tidakkah kamu ingin mendengar apa yang orang tua dari Ele... anak kecil itu ingin katakan padamu?",
  ui_story_32180401_1_79_dialog_content = "Hanya beberapa kata ucapan terima kasih, kurasa.",
  ui_story_32180401_1_80_dialog_content = "Saya puas asalkan anak itu sampai di rumah dengan selamat.",
  ui_story_32180401_1_81_dialog_content = "Kamu bisa jadi aneh kadang-kadang, seperti sekarang, ketika kamu bahkan tidak ingin tahu nama anak kecil itu...",
  ui_story_32180401_1_82_dialog_content = "Sekarang bukan waktunya bagi saya untuk mencari tahu.",
  ui_story_32180401_1_83_dialog_content = "May Bolehkah saya bertanya, Lady Sheol?",
  ui_story_32180401_1_84_dialog_content = "Tembak!",
  ui_story_32180401_1_85_dialog_content = "Kenapa tiba-tiba beramal?",
  ui_story_32180401_1_86_dialog_content = "Apakah ini terlihat seperti amal bagi kamu? Bukankah selama ini kamu juga melakukan hal yang serupa?",
  ui_story_32180401_1_87_dialog_content = "Apa? Benarkah?",
  ui_story_32180401_1_88_dialog_content = "Ini bukan amal untuk saya.",
  ui_story_32180401_1_89_dialog_content = "Saya baru saja menyadari bahwa anak itu memiliki bakat untuk angka saat dia bersama saya.",
  ui_story_32180401_1_90_dialog_content = "Dengan beberapa pelatihan, dia bisa menjadi akuntan yang sangat baik untuk Cloudrover.",
  ui_story_32180401_1_91_dialog_content = "Anda tampak yakin bahwa anak itu akan bekerja untuk Cloudrover di masa depan, bukan?",
  ui_story_32180401_1_92_dialog_content = "Yah, itu rahasia perusahaan.",
  ui_story_32180401_1_93_dialog_content = "Tapi itu tidak ada hubungannya dengan mengirimnya kembali ke orang tuanya, bukan?",
  ui_story_32180401_1_94_dialog_content = "Tenslotte, mempertahankan dia di Cloudrover Guild adalah apa yang akan dilakukan oleh seorang pengusaha yang cerdik, bukan?",
  ui_story_32180401_1_95_dialog_content = "Sekarang bukan waktunya untuk itu.",
  ui_story_32180401_1_96_dialog_content = "Atau lebih tepatnya, tempat terbaik untuknya di usianya bukanlah di guild.",
  ui_story_32180401_1_97_dialog_content = "...",
  ui_story_32180401_1_98_dialog_content = "Saya pikir kau akan mengajukan pertanyaan berikutnya karena kebiasaan.",
  ui_story_32180401_1_99_dialog_content = "Tebak kamu juga sudah dewasa. Mungkin saya harus mengevaluasi ulang penilaian saya tentang kamu.",
  ui_story_32180401_1_100_dialog_content = "Kamu mungkin bertanya-tanya kenapa aku peduli pada anak itu, benar?",
  ui_story_32180401_1_101_dialog_content = "Sebenarnya, saya menyadari anak itu memiliki bakat untuk angka saat dia bersama saya.",
  ui_story_32180401_1_102_dialog_content = "Dengan beberapa pelatihan, dia bisa menjadi akuntan yang sangat baik untuk Cloudrover.",
  ui_story_32180401_1_103_dialog_content = "Itu tidak ada hubungannya dengan mengirimnya kembali ke orang tuanya, bukan?",
  ui_story_32180401_1_104_dialog_content = "Tenslotte, mempertahankan dia di Cloudrover Guild adalah apa yang akan dilakukan oleh seorang pengusaha yang cerdik, bukan?",
  ui_story_32180401_1_105_dialog_content = "Sekarang bukan waktunya untuk itu.",
  ui_story_32180401_1_106_dialog_content = "Atau lebih tepatnya, tempat terbaik untuknya di usianya bukanlah di guild.",
  ui_story_32180401_1_107_dialog_content = "Sudah kuduga…",
  ui_story_32180401_1_108_dialog_content = "Kamu memang memiliki tempat khusus di hatimu untuk Elena, bukan? Baik ketika kamu merawatnya atau berbicara tentangnya...",
  ui_story_32180401_1_109_dialog_content = "Tidak sopan untuk mengintip ke dalam pikiran seorang wanita, klienku yang terhormat.",
  ui_story_32180401_1_110_dialog_content = "Ini hanya perasaan. Tidak ada kekuatan mental yang terlibat.",
  ui_story_32180401_1_111_dialog_content = "Apakah itu begitu jelas?",
  ui_story_32180401_1_112_dialog_content = "Sepertinya aku harus belajar lebih baik lagi dalam mengendalikan emosiku.",
  ui_story_32180401_1_113_dialog_content = "Sebenarnya, ada alasan penting lainnya mengapa aku melakukan itu.",
  ui_story_32180401_1_114_dialog_content = "Saya hanya... tidak ingin gadis itu tumbuh besar tanpa keluarganya.",
  ui_story_32180401_1_115_dialog_content = "Itu saja.",
  ui_story_32180601_1_2_dialog_content = "Celepuk—",
  ui_story_32180601_1_3_dialog_content = "Salam, Kurator!",
  ui_story_32180601_1_4_dialog_content = "Bagus... bagus, cukup bersemangat...",
  ui_story_32180601_1_5_dialog_content = "Penyanyi dan bandnya sudah siap. Haruskah kita memulai pertunjukan sekarang?",
  ui_story_32180601_1_6_dialog_content = "Sekarang? Tidak, kita harus menunggu tamu-tamu.",
  ui_story_32180601_1_7_dialog_content = "Tuan, pengacau telah diikat dan dibawa ke ruang bawah tanah.",
  ui_story_32180601_1_8_dialog_content = "Bagaimana kamu ingin menghukumnya agar dia belajar pelajarannya?",
  ui_story_32180601_1_9_dialog_content = "Hukum... Atau sebaiknya kita biarkan dia sendiri untuk meredakan amarahnya?",
  ui_story_32180601_1_10_dialog_content = "Pemimpin dari geng kecil ingin memberikan penghormatan dengan gestur penghormatan. Apakah kamu ingin menerimanya?",
  ui_story_32180601_1_11_dialog_content = "Ayo lewati itu! Siapa tahu apa yang akan terjadi setelah itu.",
  ui_story_32180601_1_12_dialog_content = "Mengerti, aku akan pastikan mereka menyerah pada fantasi bodoh mereka.",
  ui_story_32180601_1_13_dialog_content = "Kami akan melakukan yang terbaik untuk membuat Anda bangga, Pak!",
  ui_story_32180601_1_14_dialog_content = "Membuatmu bangga!",
  ui_story_32180601_1_15_dialog_content = "Aku benci mengulangi diriku sendiri, tapi aku tidak memiliki tempat ini.",
  ui_story_32180601_1_16_dialog_content = "Karakter rendah hati Anda patut dikagumi, pak. Tidak ada keraguan tentang itu.",
  ui_story_32180601_1_17_dialog_content = "Berdasarkan dokumen Ms. Sheol, kamu adalah satu-satunya kurator di sini.",
  ui_story_32180601_1_18_dialog_content = "Mohon terima penghormatan tulus kami!!!",
  ui_story_32180601_1_19_dialog_content = "Bagaimana bisa berakhir seperti ini...",
  ui_story_32180601_1_20_dialog_content = "Jika saya tahu, saya tidak akan merespon undangan itu...",
  ui_story_32180601_1_21_dialog_content = "<color=#e8d9bb>Tercinta PlayerName, sudah lama sejak kita terakhir berbicara, saya harap ini menemukanmu dalam keadaan baik.</color>",
  ui_story_32180601_1_22_dialog_content = "<color=#e8d9bb>Dengan Persekutuan Cloudrover yang sedang berkembang, saya memiliki hal penting untuk dibicarakan dengan Anda.</color>",
  ui_story_32180601_1_23_dialog_content = "<color=#e8d9bb>Saya akan sangat berterima kasih jika Anda dapat menemukan waktu untuk bertemu dengan saya. Saya menantikan kabar dari Anda.</color>",
  ui_story_32180601_1_24_dialog_content = "<color=#e8d9bb>Dengan cinta, Sheol</color>",
  ui_story_32180601_1_25_dialog_content = "Kertas surat mewah dan segel lilin saja sudah menunjukkan kemewahan.",
  ui_story_32180601_1_26_dialog_content = "Tapi undangan ini, yang datang tiba-tiba, memberiku firasat buruk.",
  ui_story_32180601_1_27_dialog_content = "Dan Nona Sheol suka menggoda orang. Meski begitu, dia mengatakan ini adalah masalah yang penting.",
  ui_story_32180601_1_28_dialog_content = "Ekspedisi bersama masih berlangsung, dan kami tidak bisa melewatkan bantuan Lady Sheol.",
  ui_story_32180601_1_29_dialog_content = "Kurasa aku harus pergi.",
  ui_story_32180601_1_30_dialog_content = "Jadi ini adalah klub baru yang baru saja diperoleh oleh Nona Sheol?",
  ui_story_32180601_1_31_dialog_content = "Ini tidak sedikit... terlalu mewah? Untuk apa ini ditujukan?",
  ui_story_32180601_1_32_dialog_content = "Apa maksudmu?",
  ui_story_32180601_1_33_dialog_content = "Oh, maaf, saya tidak bermaksud jadi kepo. Lady Sheol yang mengundang saya.",
  ui_story_32180601_1_34_dialog_content = "Permisi, kamu adalah Tuan Navigator, benar? Silakan ke sini!",
  ui_story_32180601_1_35_dialog_content = "Lady Sheol sudah menunggu kamu cukup lama, tapi... kenapa kamu berpakaian seperti ini?",
  ui_story_32180601_1_36_dialog_content = "Hah? Aku pikir aku harus berpakaian untuk acara seperti ini.",
  ui_story_32180601_1_37_dialog_content = "Tentu saja. Silakan ikuti aku.",
  ui_story_32180601_1_38_dialog_content = "Oke!",
  ui_story_32180601_1_39_dialog_content = "Ini adalah tempatnya.",
  ui_story_32180601_1_40_dialog_content = "A-Apakah kamu yakin?",
  ui_story_32180601_1_41_dialog_content = "Benar, Lady Sheol memerintahkan saya untuk mengantar kamu ke sini saat kamu tiba.",
  ui_story_32180601_1_42_dialog_content = "Kupikir kau akan datang dengan mengenakan jubah mandi.",
  ui_story_32180601_1_43_dialog_content = "(Sebuah rumah mandi mewah... Apa yang terjadi...)",
  ui_story_32180601_1_44_dialog_content = "Hmm, mungkin aku harus saja—",
  ui_story_32180601_1_45_dialog_content = "PlayerName, sayangku, akhirnya kamu datang juga.",
  ui_story_32180601_1_46_dialog_content = "Bisakah kamu tidak membuatku menunggu di sini lebih lama lagi?",
  ui_story_32180601_1_47_dialog_content = "M-May Bolehkah aku masuk?",
  ui_story_32180601_1_48_dialog_content = "Saya tidak melihat ada yang salah dengan itu. Kita di sini untuk membahas masalah bisnis, bukan?",
  ui_story_32180601_1_49_dialog_content = "Masuklah.",
  ui_story_32180601_1_50_dialog_content = "A... Aku paham sekarang!",
  ui_story_32180601_1_51_dialog_content = "Uapnya sangat tebal... Aku hampir tidak bisa melihat apa-apa.",
  ui_story_32180601_1_52_dialog_content = "Sungguh mengecewakan. Kenapa kamu berpakaian begitu formal? Aku berharap bisa mengajakmu mandi bersama.",
  ui_story_32180601_1_53_dialog_content = "Apa?!",
  ui_story_32180601_1_54_dialog_content = "Begitu malu sampai-sampai kamu lari ke luar, betapa menggemaskannya, sayangku.",
  ui_story_32180601_1_55_dialog_content = "Bukankah saya sebutkan dalam undangan? Saya sangat menantikan kedatangan Anda.",
  ui_story_32180601_1_56_dialog_content = "Tapi, tapi siapa yang akan menyangka itu akan ada di rumah mandi?",
  ui_story_32180601_1_57_dialog_content = "Ini hanya bagian dari klub, sayangku. Kenapa kamu begitu terkejut? Saya berpakaian dengan baik. Apakah kamu ingin memeriksa?",
  ui_story_32180601_1_58_dialog_content = "Mandi ini memiliki 19 jenis ramuan berbeda di dalamnya, dan airnya selalu dengan suhu yang tepat.",
  ui_story_32180601_1_59_dialog_content = "Sebagai tamu yang paling saya hormati, umpan balik Anda sangat berharga.",
  ui_story_32180601_1_60_dialog_content = "Baiklah! Mari kita minta kepala pembantu membawakanmu handuk kimono. Apakah kamu mau menemani saya?",
  ui_story_32180601_1_61_option_content = "Mengapa kita tidak... membicarakan bisnis terlebih dahulu?",
  ui_story_32180601_1_62_dialog_content = "Hehe, kamu benar-benar tidak sabaran...",
  ui_story_32180601_1_63_dialog_content = "Tapi aku menikmati hasrat ini untuk mencari peluang bisnis.",
  ui_story_32180601_1_64_option_content = "Tolong berhenti menggodaku...",
  ui_story_32180601_1_65_dialog_content = "Saya percaya ini masih bagian dari bisnis kami.",
  ui_story_32180601_1_66_dialog_content = "Tapi kamu terlihat sangat memerah. Mungkin ini bukan tempat terbaik untukmu.",
  ui_story_32180601_1_67_dialog_content = "Kamu bisa pergi ke balai terlebih dahulu. Saya akan ke sana dalam sebentar untuk membahas masalah kita yang sebenarnya, masalah yang sebenarnya.",
  ui_story_32180601_1_68_dialog_content = "Kamu yakin ini urusan bisnis, kan?",
  ui_story_32180601_1_69_dialog_content = "Tentu saja, dan itu adalah sesuatu yang akan sangat menguntungkan kamu. Kamu juga sebaiknya menantikannya.",
  ui_story_32180601_1_70_dialog_content = "Apakah ada yang bisa saya bantu? Ini adalah cangkir teh ketigamu.",
  ui_story_32180601_1_71_dialog_content = "Aku baik-baik saja...",
  ui_story_32180601_1_72_dialog_content = "Dan pipimu tetap memerah.",
  ui_story_32180601_1_73_dialog_content = "Bisakah kamu turunkan pendingin ruangan untukku? Terima kasih.",
  ui_story_32180601_1_74_dialog_content = "<color=#e8d9bb>Krieeek...</color>",
  ui_story_32180601_1_75_dialog_content = "Saya minta maaf atas penundaannya, sayangku.",
  ui_story_32180601_1_76_dialog_content = "Ini kamu, berapa lama kamu menghabiskan—",
  ui_story_32180601_1_77_dialog_content = "Saya hanya ingin berdandan untuk cocok dengan pakaianmu.",
  ui_story_32180601_1_78_dialog_content = "Butuh beberapa waktu bagiku.",
  ui_story_32180601_1_79_dialog_content = "Wow, gaunnya...",
  ui_story_32180601_1_80_dialog_content = "Kamu mempesona setiap hari, tapi gaun ini...",
  ui_story_32180601_1_81_dialog_content = "Yah? Apakah itu sudah cukup untukmu?",
  ui_story_32180601_1_82_dialog_content = "Berhenti bercanda... Ini bukan masalah cukup baik atau tidak. Saya merasa malu sekarang.",
  ui_story_32180601_1_83_dialog_content = "Jangan bilang begitu, Tuan Navigator, lagipula, kamulah pemilik di sini.",
  ui_story_32180601_1_84_dialog_content = "Aku... pemiliknya?",
  ui_story_32180601_1_85_dialog_content = "Benar, saya mengundang Anda ke sini hari ini untuk mentransfer kepemilikan klub ini ke perawatan Anda.",
  ui_story_32180601_1_86_dialog_content = "Pfttt—Maaf, uhuk, uhuk... Apa itu?!",
  ui_story_32180601_1_87_dialog_content = "Sebagai pelanggan yang paling saya hargai, hanya pantas jika saya memberi Anda sesuatu.",
  ui_story_32180601_1_88_dialog_content = "Bukan hanya sesuatu itu!",
  ui_story_32180601_1_89_dialog_content = "Jika kamu tidak bisa menjelaskannya, aku pasti tidak akan menerimanya...",
  ui_story_32180601_1_90_dialog_content = "Tentu saja—saya punya alasan.",
  ui_story_32180601_1_91_dialog_content = "Klub mewah ini dulunya milik sainganku, seorang bos pasar gelap.",
  ui_story_32180601_1_92_dialog_content = "Saya mengambil alih klub ini untuk menyusup ke pasar gelap di pesta pembukaan besar-besaran.",
  ui_story_32180601_1_93_dialog_content = "Kalau orang-orang sampai tahu bahwa aku mengambil alih klub ini...",
  ui_story_32180601_1_94_dialog_content = "Sepertinya saya mencoba masuk ke wilayah mereka. Terlalu jelas, bukan menurutmu? Tidak ada yang akan datang.",
  ui_story_32180601_1_95_dialog_content = "Seperti yang saya harapkan dari kamu, sangat peka memang.",
  ui_story_32180601_1_96_dialog_content = "Apa lagi yang bisa aku lakukan? Ini mungkin bisa menjadi pesta pembukaan terdiam dalam sejarah Umbraton...",
  ui_story_32180601_1_97_dialog_content = "... Cukup rahasiakan bahwa kamu telah membelinya, bukankah itu tidak apa-apa?",
  ui_story_32180601_1_98_dialog_content = "Jaringan intelijen di Umbraton lebih canggih daripada yang kamu sadari. Berita tentang akuisisi klub oleh pembeli anonim telah disebarluaskan.",
  ui_story_32180601_1_99_dialog_content = "Dengan begitu banyak yang bergantung pada ini, tidak mengherankan jika orang-orang mulai berspekulasi tentang siapa yang membeli tempat ini.",
  ui_story_32180601_1_100_dialog_content = "Kekhawatiran paling mendesak pada titik ini adalah untuk mendapatkan pembeli yang sah untuk meredam spekulasi eksternal yang tidak perlu.",
  ui_story_32180601_1_101_dialog_content = "Jadi, siapa yang paling cocok untuk mengirim undangan kepada para pemimpin semua guild di Umbraton?",
  ui_story_32180601_1_102_dialog_content = "...Aku?",
  ui_story_32180601_1_103_dialog_content = "Kamu benar-benar memahami niatku.",
  ui_story_32180601_1_104_dialog_content = "Jadi ini alasanmu memberikan klub ini padaku...",
  ui_story_32180601_1_105_dialog_content = "Tapi, ini tidak tanpa cacat, bukan?",
  ui_story_32180601_1_106_dialog_content = "Misalnya, aku si Caelestite... Bukankah cukup mencolok?",
  ui_story_32180601_1_107_dialog_content = "Dan itu tidak terdengar benar... Maksudku, leluhurku akan menangis jika mereka tahu aku memiliki klub seperti itu.",
  ui_story_32180601_1_108_dialog_content = "Jadi, apakah kita masih harus...",
  ui_story_32180601_1_109_dialog_content = "Oh sayang, kau tidak akan bilang tidak, kan?",
  ui_story_32180601_1_110_dialog_content = "Uh, mungkin kita harus merencanakan semuanya?",
  ui_story_32180601_1_111_dialog_content = "Tidak ada waktu untuk itu. Undangan telah disiapkan dan menunggu persetujuan Anda untuk didistribusikan.",
  ui_story_32180601_1_112_dialog_content = "Tentu saja, atas nama Anda.",
  ui_story_32180601_1_113_dialog_content = "Atas namaku?!",
  ui_story_32180601_1_114_dialog_content = "Saya tidak berpikir ada yang akan percaya cerita saya, baik guild maupun boss pasar gelap.",
  ui_story_32180601_1_115_dialog_content = "Tidak, tidak, Sayang, kamu benar-benar tidak tahu apa-apa tentang pesona dirimu.",
  ui_story_32180601_1_116_dialog_content = "Kamu adalah satu-satunya individu yang mampu menyatukan faksi-faksi yang berbeda di Astra.",
  ui_story_32180601_1_117_dialog_content = "Hanya kamu yang bisa menjembatani jurang antara para pemimpin yang saling tidak percaya ini.",
  ui_story_32180601_1_118_dialog_content = "Belum lagi, kamu adalah rekan penting bagi Shadowlord. Ini bukan rahasia.",
  ui_story_32180601_1_119_dialog_content = "Persekutuan Umbraton?! Memang... ini cukup kebetulan...",
  ui_story_32180601_1_120_dialog_content = "Dengan pandangan positif Anda, optimisme, dan pengaruh yang tak tertandingi di seluruh Astra...",
  ui_story_32180601_1_121_dialog_content = "Ketika kamu ingin mendirikan sebuah klub di Umbraton untuk mengumpulkan intelijen, berdagang barang, dan mengadakan pertemuan untuk para pemimpin...",
  ui_story_32180601_1_122_dialog_content = "Siapa yang berani menolakmu?",
  ui_story_32180601_1_123_dialog_content = "Kamu hampir meyakinkanku...",
  ui_story_32180601_1_124_dialog_content = "Jangan khawatir. Jika ada yang mencoba menggangumu, aku akan melindungimu.",
  ui_story_32180601_1_125_dialog_content = "Aku akan melakukan yang terbaik untuk mendukung dan melindungi kamu, sayangku.",
  ui_story_32180601_1_126_dialog_content = "Percayalah padaku, bekerja sama denganku, dan kita berdua akan mendapatkan keuntungan.",
  ui_story_32180601_1_127_dialog_content = "Oke.",
  ui_story_32180601_1_128_dialog_content = "Baiklah, saya akan menandatangani perjanjian itu saja.",
  ui_story_32180601_1_129_dialog_content = "Panggilan bagus! Ini adalah peluang emas bagi kita berdua.",
  ui_story_32180601_1_130_dialog_content = "Benar, rencana Anda benar-benar membuat saya terkesan, itu pasti.",
  ui_story_32180601_1_131_dialog_content = "Yang lebih penting... Aku percaya padamu.",
  ui_story_32180601_1_132_dialog_content = "Berinvestasi pada kamu pasti ada nilainya, kan?",
  ui_story_32180601_1_133_dialog_content = "Humph, tentu saja.",
  ui_story_32180601_1_134_dialog_content = "Saya harap kamu mengerti, kita lebih dari sekedar mitra bisnis.",
  ui_story_32180601_1_135_dialog_content = "Aku sangat ingin melihat penampilanmu di pesta pembukaan...",
  ui_story_32180601_1_136_dialog_content = "<color=#e8d9bb>Dan di sinilah aku, di pesta pembukaan, menunggu dengan cemas...</color>",
  ui_story_32180601_1_137_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_32180601_1_138_dialog_content = "Hmm? Jadi kamu adalah pemilik baru klub ini?",
  ui_story_32180601_1_139_dialog_content = "Bukankah ini hanya seorang pemula? Bisakah dia benar-benar menjadi kurator di sini?",
  ui_story_32180601_1_140_dialog_content = "Jangan bilang kamu berencana membuka taman kanak-kanak di sini?",
  ui_story_32180601_1_141_dialog_content = "Hahahahaha!",
  ui_story_32180601_1_142_dialog_content = "(Aku telah membuat beberapa musuh di Umbraton, jadi aku rasa ini pasti akan terjadi...)",
  ui_story_32180601_1_143_dialog_content = "(Namun, ini adalah hari pertama bisnis; saya tidak boleh merusaknya!)",
  ui_story_32180601_1_144_dialog_content = "(Saya harus membantu Lady Sheol...)",
  ui_story_32180601_1_145_dialog_content = "*batuk* Kalian berdua, tahu tidak kalian sedang berbicara dengan siapa?",
  ui_story_32180601_1_146_dialog_content = "Hah? Berani-beraninya kau berbicara padaku seperti ini di Umbraton. Ulangi lagi dan aku akan membuat tempat ini terbalik.",
  ui_story_32180601_1_147_dialog_content = "Jika kamu mencoba sesuatu, kamu akan menyesal. Kamu tidak akan bisa keluar dari sini dalam keadaan hidup.",
  ui_story_32180601_1_148_dialog_content = "Apa kaubilang!?",
  ui_story_32180601_1_149_dialog_content = "Maaf, aku terlambat, Navigator.",
  ui_story_32180601_1_150_dialog_content = "…?!",
  ui_story_32180601_1_151_dialog_content = "Betapa kasarnya saya terlambat dalam acara yang begitu penting!",
  ui_story_32180601_1_152_dialog_content = "Pastikan untuk menerima hadiah dari Cloudrover Guild.",
  ui_story_32180601_1_153_dialog_content = "Apakah itu... cek dari Cloudrover Guild? Dan berapa banyak nolnya?!",
  ui_story_32180601_1_154_dialog_content = "Haruskah saya membayar sebanyak ini untuk perlindungan?",
  ui_story_32180601_1_155_dialog_content = "Penawaran saya hanya sebagian kecil dari biaya ekspedisi bersama. Saya harap Anda tetap menerimanya.",
  ui_story_32180601_1_156_dialog_content = "Yang saya minta hanyalah kamu mengakui sponsor dari Persekutuan Cloudrover saat membahas hal-hal penting dengan Grand Marshal atau Shadowlord.",
  ui_story_32180601_1_157_dialog_content = "Ini akan menjadi kehormatan terbesar saya.",
  ui_story_32180601_1_158_dialog_content = "Tunggu, Lady Sheol, apakah kamu mengatakan bahwa dia terhubung dengan ekspedisi bersama...?",
  ui_story_32180601_1_159_dialog_content = "Bukankah orang ini hanya mengandalkan hubungannya dengan markas besar dan penggemar gila itu? Lovegators?",
  ui_story_32180601_1_160_dialog_content = "Kalian berdua telah membuat keributan sejak tadi...",
  ui_story_32180601_1_161_dialog_content = "Kurator baru ini tidak suka keramaian, saya rasa sudah waktunya kami memintamu untuk pergi...",
  ui_story_32180601_1_162_dialog_content = "Kami tidak ingin membuat kurator merasa terganggu dan merusak kesepakatan untuk semua orang.",
  ui_story_32180601_1_163_dialog_content = "Silakan kembali!",
  ui_story_32180601_1_164_dialog_content = "Aku dengar bahwa Shadowlord juga ingin bertemu dengan kurator baru.",
  ui_story_32180601_1_165_dialog_content = "Hei, tunggu sebentar, bagaimana mungkin kita di sini untuk membuat masalah!",
  ui_story_32180601_1_166_dialog_content = "Jika Shadowlord benar-benar memberi kita kehadirannya... Tolong, biarkan saya membuat investasi!",
  ui_story_32180601_1_167_dialog_content = "S-Sama di sini! Jika ada kesempatan untuk bekerja dengan Illumina, saya pasti tertarik.",
  ui_story_32180601_1_168_dialog_content = "Apa yang kamu tunggu? Ayo ambil posisi!",
  ui_story_32180601_1_169_dialog_content = "Apa yang terjadi... Hah?!",
  ui_story_32180601_1_170_dialog_content = "<color=#e8d9bb>Jadi, pesta pembukaan menjadi upacara penandatanganan.</color>",
  ui_story_32180601_1_171_dialog_content = "<color=#e8d9bb>Dan kontrak-kontrak yang ditandatangani dalam setengah hari saja mewakili jumlah uang yang belum pernah ada sebelumnya...</color>",
  ui_story_32180601_1_172_dialog_content = "Fiuh... Ini membunuhku...",
  ui_story_32180601_1_173_dialog_content = "Kamu telah melampaui dirimu sendiri! Aku melihatmu dalam cahaya yang benar-benar baru.",
  ui_story_32180601_1_174_dialog_content = "Jangan terlalu mudah dalam penilaianmu. Saya pikir ada beberapa penawaran yang sedang berlangsung.",
  ui_story_32180601_1_175_dialog_content = "Aku memberimu isyarat, tapi yang kamu lakukan hanya menghisap pipa dan mendesakku untuk menandatangani. Jika ada yang salah, jangan datang menangis padaku!",
  ui_story_32180601_1_176_dialog_content = "Tidak usah khawatir, semua yang perlu kamu lakukan adalah menandatanganinya. Aku masih memiliki banyak hal lain untuk dipertimbangkan.",
  ui_story_32180601_1_177_dialog_content = "Tenang saja, saya bisa menangani sebagian besar transaksi dengan sempurna; hanya ada beberapa saja.",
  ui_story_32180601_1_178_dialog_content = "Mungkin ini sedikit lepas kendali.",
  ui_story_32180601_1_179_dialog_content = "Jadi... bukankah geng itu akan datang mencari masalah padaku?!",
  ui_story_32180601_1_180_dialog_content = "Tidak, tidak, saya berhenti. Pilih orang lain untuk kurator!",
  ui_story_32180601_1_181_dialog_content = "Oh tidak, itu tidak bisa. Bahkan kamu harus mematuhi semangat kontrak.",
  ui_story_32180601_1_182_dialog_content = "Lagipula, kau 'kan baru saja mengalaminya bukan?",
  ui_story_32180601_1_183_dialog_content = "Kehidupan orang kaya? Aku baik-baik saja sebagai Caelestite!",
  ui_story_32180601_1_184_dialog_content = "Itu bukan yang saya maksud, saya sedang membicarakan tentang layanan keamanan dari Cloudrover Guild.",
  ui_story_32180601_1_185_dialog_content = "Silakan kembali.",
  ui_story_32180601_1_186_dialog_content = "Yang perlu kamu lakukan hanyalah membuat satu kesepakatan lagi dengan saya, dan layanan keamanan Cloudrover Guild akan gratis untukmu selamanya!",
  ui_story_32180601_1_187_dialog_content = "Tapi... Aku menolak!",
  ui_story_32180601_1_188_dialog_content = "Kamu sama pemalunya seperti biasa, bukan, sayangku...",
  ui_story_32180601_1_189_dialog_content = "Namun, karena kamu telah menandatangani begitu banyak kontrak hari ini, beberapa orang mungkin tak terhindarkan akan cemburu. Lebih baik tinggal di klub dan beristirahat yang baik.",
  ui_story_32180601_1_190_dialog_content = "Meninggalkan Umbraton di tengah malam tidak aman. Ada kemungkinan besar kamu bisa diculik.",
  ui_story_32180601_1_191_dialog_content = "Kamu tidak pernah menyebutkan ada risiko seperti itu sebelumnya!?",
  ui_story_32180601_1_192_dialog_content = "Kamu tidak akan pernah tinggal di sini jika aku memberitahumu. Aku takut kamu sudah lari dengan Colossus yang patut ditiru itu.",
  ui_story_32180601_1_193_dialog_content = "Jadi, izinkan aku merawatmu dengan baik malam ini dan rasakan mandi yang hebat!",
  ui_story_32180601_1_194_dialog_content = "Hah? Ah? Apa—!!!"
}
return config
